package com.eventpulse.handler;
import com.amazonaws.services.lambda.runtime.*; import com.amazonaws.services.lambda.runtime.events.*; import com.eventpulse.config.DynamoDbConfig; import com.eventpulse.repository.*; import com.eventpulse.service.*; import com.eventpulse.util.ResponseUtil;
public class RegistrationHandler implements RequestHandler<APIGatewayV2HTTPEvent,APIGatewayV2HTTPResponse>{private final RegistrationService service; public RegistrationHandler(){var db=DynamoDbConfig.enhancedClient();var events=new EventService(new EventRepository(db,DynamoDbConfig.table("EVENTS_TABLE","EventPulse-Events")));service=new RegistrationService(new RegistrationRepository(db,DynamoDbConfig.table("REGISTRATIONS_TABLE","EventPulse-Registrations")),events);} public RegistrationHandler(RegistrationService s){service=s;} public APIGatewayV2HTTPResponse handleRequest(APIGatewayV2HTTPEvent r,Context c){try{String method=r.getRequestContext().getHttp().getMethod();var p=r.getPathParameters();String id=p==null?null:p.get("registrationId");if(method.equals("DELETE")&&id!=null)return ResponseUtil.response(200,service.cancel(id,EventHandler.user(r)));return ResponseUtil.error(404,"NOT_FOUND","Route not found");}catch(Exception e){return EventHandler.handleError(e);}}}
